Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Variable P : PESK.sink_policy.
Hypothesis LY : PMU.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis SPB0 : 0 <= PESK.sp_B P.
Let KL := PECKU.klayout_U L LY.
Variable R0 : bvmap 5 word.
Variable M0 : word -> option byte.
Variable model0 : Model.
Variables (sp ptr ra : Z).
Variable payload : list byte.
Variable LB0 : list (Z * Z).
Variable cr0 : credit.
Variable g : PMST.st.
Hypothesis Hn : PECHU.n payload < 2 ^ 26.
Hypothesis Hcr0 : PMSP.credit_le (PECTU.TOPK, PECTU.TOPB0 + PESK.sp_B P) cr0.
Hypothesis Hgp : getr R0 (reg 3) = Z_to_bv 64 67584.
Hypothesis Htp : getr R0 (reg 4) = Z_to_bv 64 (pa_tp AD).

Lemma stage3 :
  PMSP.reader_ctor_spec RSEGS AD L HI ->
  forall (fx : FPState) R M model cr s s2 sm K,
    PECHU.H2 L HI P R0 M0 model0 sp ra payload LB0 cr0 g R M model cr s s2 sm -> K [] ->
    (forall (fx1 : FPState) R1 M1 model1 cr1 qc b,
        PECHU.H3 L HI P R0 M0 model0 sp ra payload LB0 cr0 g R1 M1 model1 cr1 s s2 sm qc b ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x34f94 M1 model1) K) ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x34f1c M model) K.
Proof.
